use std::rc::Rc;
use std::cell::RefCell;
use std::collections::VecDeque;

// Definition for a binary tree node.
#[derive(Debug, PartialEq, Eq)]
pub struct TreeNode {
  pub val: i32,
  pub left: Option<Rc<RefCell<TreeNode>>>,
  pub right: Option<Rc<RefCell<TreeNode>>>,
}

impl TreeNode {
  #[inline]
  pub fn new(val: i32) -> Self {
    TreeNode {
      val,
      left: None,
      right: None
    }
  }
}

struct Solution;

impl Solution {
    pub fn is_cousins(root: Option<Rc<RefCell<TreeNode>>>, x: i32, y: i32) -> bool {
        if root.is_none() { return false; }

        let root = root.unwrap();
        let mut queue = VecDeque::new();
        queue.push_back((root.clone(), None)); // (node, parent_val)

        while !queue.is_empty() {
            let level_size = queue.len();
            let mut x_parent = None;
            let mut y_parent = None;

            for _ in 0..level_size {
                let (node, parent) = queue.pop_front().unwrap();
                let node_val = node.borrow().val;

                if node_val == x {
                    x_parent = parent;
                }
                if node_val == y {
                    y_parent = parent;
                }

                if let Some(left) = &node.borrow().left {
                    queue.push_back((left.clone(), Some(node_val)));
                }
                if let Some(right) = &node.borrow().right {
                    queue.push_back((right.clone(), Some(node_val)));
                }
            }

            if x_parent.is_some() && y_parent.is_some() {
                return x_parent != y_parent;
            }
            if x_parent.is_some() || y_parent.is_some() {
                // Found one but not the other at this level
                return false;
            }
        }

        false
    }
}

